{"output": "def transform(grid):
    # Stamp the sparse marker shape at all matches.
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row if v != 0)
    if not counts:
        return [row[:] for row in grid]
    bg = counts.most_common(1)[0][0]
    colors = set(counts) - {bg}
    if len(colors) != 1:
        return [row[:] for row in grid]
    color = next(iter(colors))
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    if not cells:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    shape = {(r-r0, c-c0) for r, c in cells}
    sh, sw = r1-r0+1, c1-c0+1
    out = [row[:] for row in grid]
    candidates = [(r,c) for r in range(h-sh+1) for c in range(w-sw+1)
                  if (r,c)!=(r0,c0) and all(grid[r+dr][c+dc]==0 for dr,dc in shape)]
    # To reject chance partial overlaps, require the whole translated bounding
    # rectangle to be background. The marked source is exempt.
    for r,c in candidates:
        if all(grid[r+dr][c+dc] == 0 for dr in range(sh) for dc in range(sw)):
            for dr,dc in shape:
                out[r+dr][c+dc] = color
    return out", "exit_code": 0, "error": null}

